Translate("esMX", "hansel-heavyhands", {
	title = "Hansel Heavyhands",
	subtitle = "Ejecutor de la Hermandad del Torio",
	found = "Puesto del Torio, cerca de la forja",
	hint = [=[Busque al enorme enano del Puesto del Torio que siempre tiene una excusa.]=],
	allegiance = "Hermandad del Torio",
	aliases = { "Hansel" },
	sections = {
		{
			title = "Resumen",
			text = [=[Hansel Heavyhands es el {link:dwarves}enano{/link} al que envía la {link:thorium-brotherhood}Hermandad del Torio{/link} cuando quiere que alguien salga malparado. Es enorme para ser un enano, y lo sabe. Dice que haría el trabajo él mismo con gusto, de no ser por sus males: dedos que se le hinchan como salchichas con el calor de la garganta, juanetes sobre sus juanetes y un resfriado del que culpa al clima. Así que pasa sus órdenes a otros y espera su informe.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Quiere que los pesados gólems de guerra que pisotean en torno a {link:the-cauldron}La Caldera{/link} queden reducidos a chatarra.
• Quiere que maten a las grandes arañas de lava de las mesetas, porque escupen fuego y asustan a los niños del {link:thorium-point}Puesto del Torio{/link}.
• Le han ordenado limpiar de incendiosaurios los estanques de lava de {link:the-slag-pit}La Fosa de la Escoria{/link}, para que la {link:syndicate}Hermandad{/link} pueda enviar abajo a sus propios exploradores.]=],
		},
	},
	mentions = {
		{ text = "Malditos sean estos dedos gordos" },
		{ text = "¡Amenaza ígnea!" },
		{ text = "¿Incendiosaurios? Más bien lo-que-seasaurios" },
	},
	bonds = {
		{ id = "taskmaster-scrange", name = "Capataz Scrange", note = "le da órdenes" },
		{ id = "master-smith-burninate", name = "Maestro herrero Burninate", note = "le da órdenes" },
	},
})

