Translate("esMX", "velarok-windblade", {
	title = "Velarok Windblade",
	subtitle = "Un hombre que ha jurado venganza",
	found = [=[Al sur del Puesto del Torio, junto a los restos destrozados de enanos Hierro Negro]=],
	hint = [=[Busque al forastero que espera entre los Hierro Negro muertos, al sur del Puesto del Torio.]=],
	allegiance = "Su propia causa",
	aliases = { "Velarok", "Kalaran Windblade" },
	sections = {
		{
			title = "Resumen",
			text = [=[Velarok Windblade ha venido a {link:searing-gorge}La Garganta de Fuego{/link} en busca de venganza, o eso dice. Habla de un padre asesinado por los {link:dark-iron-dwarves}Hierro Negro{/link} de {link:the-cauldron}La Caldera{/link}, y de súplicas de justicia que los magistrados de {link:stormwind-city}Ventormenta{/link} no quisieron escuchar. El reino, dice con amargura, prefiere fingir que este rincón del mundo no existe antes que enviar aquí a sus soldados. Así que ha venido él mismo, sin más compañía que un torpe escudero, y espera a alguien lo bastante audaz para ayudarle a golpear.]=],
		},
		{
			title = "Importancia",
			text = [=[Velarok ofrece lo que la garganta rara vez ofrece: un plan. No pretende luchar contra los {link:dark-iron-dwarves}Hierro Negro{/link} espada contra espada. Pretende primero cegarlos, quemando las torres de vigía que guardan {link:the-cauldron}La Caldera{/link}, y después golpear antes de que puedan reponerse. A quienes le ayuden les promete riquezas más allá de sus sueños.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Cuenta su historia a cualquier viajero que quiera escucharla.
• Reúne corazones de llama y aceite de gólem para una antorcha que ningún elemento puede apagar.
• Deshace las dagas de torio de los esclavistas {link:dark-iron-dwarves}Hierro Negro{/link} para forjar el mango de la antorcha.
• Extrae la magia de un símbolo de {red:ragnaros}Ragnaros{/red}, arrebatado al {link:twilight-s-hammer}Martillo Crepuscular{/link}, para formar su cubierta.]=],
		},
	},
	chapters = {
		{
			title = "La Antorcha de la Venganza",
			hint = [=[Reúna lo que Velarok necesita para su antorcha, y vea cómo la fabrica.]=],
			text = [=[La antorcha se hizo con la propia garganta. Su llama vino de los corazones de los elementales de fuego y del aceite de los gólems de guerra. Su mango se forjó con el torio encantado de las propias hojas de los esclavistas. Su cubierta se labró con un ídolo del Señor del Fuego, cuya magia inmunda Velarok consideró perfecta para la tarea. Se inclinó largo rato sobre las piezas y pidió paciencia a quien le ayudaba. Cuando estuvo terminada, quien alzaba la antorcha sentía oleadas de odio y de ira que lo atravesaban.]=],
		},
		{
			title = "El embaucador",
			hint = "Prenda fuego a las cuatro torres de La Caldera.",
			text = [=[Las torres ardieron, y el escudero de Velarok gritó que era glorioso. Entonces Velarok se despojó de su forma de hombre. Era un draco del Vuelo Negro, y nunca había existido un padre asesinado. Solo necesitaba que se destruyera la primera línea de defensa de los {link:dark-iron-dwarves}Hierro Negro{/link}, y sabía que ningún mortal habría ayudado a la legión de {link:blackrock-clan}Roca Negra{/link} si se lo hubiera pedido abiertamente. Perdonó a quienes le habían servido, para que vivieran y vieran el caos de la inminente invasión de la garganta. Les dejó un montón de baratijas, y con ellas la muda de un dragón negro, que según dijo sus congéneres de {link:burning-steppes}Las Estepas Ardientes{/link} podían usar para reforzar su oficio. Luego emprendió el vuelo hacia la {link:blackrock-mountain}Montaña Roca Negra{/link}.]=],
		},
	},
	mentions = {
		{ text = "Castigo divino" },
		{ text = "La llama perfecta" },
		{ text = "Forjar el mango" },
		{ text = "La cubierta de la llama" },
		{ text = "La Antorcha de la Venganza" },
		{ text = "La Antorcha de la Venganza, ligada a su portador" },
		{ text = "El escudero {link:squire-maltrake}Maltrake{/link}" },
		{ text = "¡Préndanles fuego!" },
		{ text = "Baratijas..." },
	},
	bonds = {
		{ id = "squire-maltrake", name = "Escudero Maltrake", note = "su sirviente" },
	},
})

Translate("esMX", "squire-maltrake", {
	title = "Escudero Maltrake",
	subtitle = "Escudero de Velarok Windblade",
	found = "Al lado de Velarok Windblade, al sur del Puesto del Torio",
	hint = "Hable con el escudero que está junto a Velarok Windblade.",
	allegiance = "Su amo",
	aliases = { "Maltrake" },
	sections = {
