		},
	},
	mentions = {
		{ text = "El escudero Maltrake" },
		{ text = "¡Préndanles fuego!" },
		{ text = "Baratijas..." },
	},
	bonds = {
		{ id = "velarok-windblade", name = "Velarok Windblade", note = "su amo" },
	},
})

Translate("esMX", "dorius-stonetender", {
	title = "Dorius Stonetender",
	subtitle = "Arqueólogo de Forjaz",
	found = "El fondo de la Excavación de Limugre",
	hint = [=[Busque al enano herido en el fondo de la excavación de Grimesilt.]=],
	allegiance = "Reino de Forjaz",
	aliases = { "Dorius" },
	sections = {
		{
			title = "Resumen",
			text = [=[Dorius Stonetender dirigió un equipo de excavación de Forjaz en {link:searing-gorge}La Garganta de Fuego{/link}. Su hermano es el conservador Thorius, de la Sala de los Exploradores. Cuando llegaron los {link:dark-iron-dwarves}Hierro Negro{/link}, se llevaron a su equipo, y Dorius quedó herido y desangrándose en el foso de {link:grimesilt-dig-site}Grimesilt{/link}. Suplica a cualquier forastero que pase que le ayude a llegar a la puerta de {link:loch-modan}Loch Modan{/link} y al camino de vuelta a {link:ironforge}Forjaz{/link}.]=],
		},
		{
			title = "Importancia",
			text = [=[Dorius fue en busca de las piedras llamadas Suntara, reliquias que también deseaban los {link:dark-iron-dwarves}Hierro Negro{/link}. Su destino pone a su afligido hermano en el camino de la venganza, y arrastra a {link:ironforge}Forjaz{/link} hacia los secretos de {link:the-cauldron}La Caldera{/link}.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Dirigió un equipo de arqueología de {link:ironforge}Forjaz{/link} en la garganta.
• Marcó {link:the-cauldron}La Caldera{/link} para que sus hombres no se perdieran allí para siempre.
• Se abrió paso luchando hacia la puerta del {link:dustfire-valley}Paso de Fraguapiedra{/link}, a pesar de sus heridas.]=],
		},
	},
	chapters = {
		{
			title = "La carta chamuscada",
			hint = "Ayude a Dorius a ponerse a salvo, y lleve lo que deja atrás.",
			text = [=[Dorius no llegó a la puerta. Sonó un disparo cuando el paso quedó a la vista, y cayó. Dejó una carta, chamuscada en los bordes, dirigida a su hermano. En ella escribió que las piedras eran reales, que los {link:dark-iron-dwarves}Hierro Negro{/link} las tenían y que su líder, Lathoric el Negro, usaba su poder para esclavizar al equipo de excavación. Los hombres habían sido llevados a {link:the-cauldron}La Caldera{/link}. Sus mentes habían sido retorcidas hacia una sola tarea: la fabricación de algo llamado {link:obsidion}Obsidion{/link}. Libérenlos, pedía. Cuando Thorius la leyó, lloró, y en nombre de la Luz juró que se cumpliría el último deseo de su hermano.]=],
		},
		{
			title = "El altar de Suntara",
			hint = [=[Baje a La Fosa de la Escoria en busca de los hombres de Dorius.]=],
			text = [=[Los arqueólogos fueron hallados en lo hondo de {link:the-slag-pit}La Fosa de la Escoria{/link}, trabajando aún aunque sus cuerpos desfallecían. Uno de ellos, moribundo, explicó que el poder de las Suntara los obligaría a terminar su tarea incluso después de la muerte. Solo el altar de Suntara podía liberarlos, y le faltaba una reliquia que el {link:twilight-s-hammer}Martillo Crepuscular{/link} guardaba en las colinas de la {link:firewatch-ridge}Cresta Vigía{/link}. La reliquia se arrebató a los sectarios y se colocó sobre el altar.]=],
		},
		{
			title = "Lathoric el Negro",
			hint = "Vea lo que despierta el altar de Suntara.",
			text = [=[Todo había sido una trampa. Dorius nunca había muerto. Cuando encontró las piedras Suntara en {link:grimesilt-dig-site}Grimesilt{/link}, el poder de {red:ragnaros}Ragnaros{/red} lo recorrió, y el Señor del Fuego le dio un nuevo propósito y un nuevo nombre: Lathoric el Negro. Se había aprovechado del dolor de su hermano para atraer rescatadores a la garganta, para que recuperaran en su nombre la última piedra del {link:twilight-s-hammer}Martillo Crepuscular{/link}. {link:obsidion}Obsidion{/link} fue construido por voluntad del Señor del Fuego, se jactó, para destruir a los orcos de la Cumbre de {link:blackrock-mountain}Roca Negra{/link} y unirlo con sus hermanos en las profundidades ardientes. Luego ordenó al gólem que se alzara. Cuando Thorius supo la verdad, palideció. Su hermano lo había traicionado a él y a todo {link:ironforge}Forjaz{/link}, y Thorius temió que, si un {link:dwarves}enano{/link} tan noble podía ser corrompido con tanta facilidad, nadie estaba a salvo.]=],
		},
	},
	mentions = {
		{ text = "Piedras Suntara" },
		{ text = "Piedras Suntara, la carta chamuscada" },
		{ text = "Justicia enana" },
		{ text = "Libérenlos" },
		{ text = "¡Álzate, {link:obsidion}Obsidion{/link}!" },
	},
	bonds = {
		{ id = "curator-thorius", name = "Conservador Thorius", note = "su hermano" },
		{ id = "obsidion", name = "Obsidion", note = "el gólem que obligaron a construir a sus hombres" },
	},
})

