Translate("esMX", "zamael-lunthistle", {
	title = "Zamael Lunthistle",
	subtitle = "Espíritu de la jaula",
	found = [=[En una jaula en la colina del Martillo Crepuscular, al noroeste de la Cresta Vigía]=],
	hint = [=[Suba al campamento del culto en la Cresta Vigía y mire dentro de su jaula.]=],
	allegiance = "Elune",
	aliases = { "Zamael" },
	sections = {
		{
			title = "Resumen",
			text = [=[Zamael Lunthistle es el fantasma de un {link:night-elves}elfo de la noche{/link}, retenido en una jaula por el {link:twilight-s-hammer}Martillo Crepuscular{/link}. De joven, en {link:darkshore}Costa Oscura{/link}, se unió al culto, abandonó a {red:elune}Elune{/red} y abrazó la adoración de los {red:old-gods}Dioses Antiguos{/red}. Muchos años después, una visión de la diosa lo despertó. Arrepentido, comenzó una plegaria a Elune en una tablilla de oro puro. El culto la encontró, lo tachó de blasfemo y le dio muerte antes de que la plegaria estuviera terminada. Su espíritu no puede partir. El culto lo mantiene enjaulado como advertencia.]=],
		},
	},
	chapters = {
		{
			title = "La tablilla de oro",
			hint = "Recupere la plegaria de Zamael del culto que se la llevó.",
			text = [=[Zamael no esperaba la absolución. Solo pidió que su plegaria se recuperara de los idólatras que la tenían y se llevara a Astarii Starseeker, en el {link:temple-of-the-moon}Templo de la Luna{/link}. Cuando ella la recibió, dijo que un alma perdida había sido devuelta a Elune.]=],
		},
	},
	mentions = {
		{ text = "Plegaria a Elune" },
		{ text = "Plegaria a Elune, la tablilla de oro" },
	},
})

